from pathlib import Path
p=Path(__file__).with_name('verify-library.cjs');s=p.read_text(encoding='utf-8');prefix=s[:s.index("const site='point-resize:v1:example.com'")];prefix=prefix.replace("'library-'+Date.now()","'preview-size-'+Date.now()")
body=r'''
const vm=require('vm');const context=vm.createContext({URL,TextEncoder,globalThis:null});context.globalThis=context;for(const file of ['video-common.js','backup.js'])vm.runInContext(fs.readFileSync(path.join(root,'src',file),'utf8'),context);const D=context.PointResizeVideoData,B=context.PointResizeBackup,errors=[];
(async()=>{try{
 let state=await request({action:'read'});assert(state.ok);const original={'point-resize:v1:example.test':{rules:[]},[D.key]:[],[D.previewKey]:{images:false}};state=await request({action:'set',revision:state.revision,writes:original});assert(state.ok);state=await request({action:'hover-size',scale:1.1,operationId:'size-one'});assert(state.ok);assert.equal(state.data[D.previewSizeKey].scale,1.1);for(const [key,value] of Object.entries(original))assert.deepEqual(state.data[key],value);check('Native size preference commits through the existing canonical writer while preserving rules, queue and the image checkbox');
 const file=path.join(home,'test-library/library.json'),before=fs.readFileSync(file);for(const scale of [.49,3.01,'1.4',null]){const invalid=await request({action:'hover-size',scale});assert.equal(invalid.ok,false);assert(fs.readFileSync(file).equals(before));}check('Out-of-range and malformed sizes are refused without changing the original library');
 const repeated=await request({action:'hover-size',scale:2,operationId:'size-one'});assert.equal(repeated.revision,state.revision);assert.equal(repeated.data[D.previewSizeKey].scale,1.1);check('A repeated operation ID cannot apply the zoom twice or overwrite a committed size');
 const backup=B.create(state.data,'0.18.6'),restored=B.parse(JSON.stringify(backup));assert.equal(restored[D.previewSizeKey].scale,1.1);assert.equal(restored[D.previewKey].images,false);assert.equal(backup.schemaVersion,1);const old={...backup,data:{[D.key]:[]}},writes=B.merge(state.data,B.parse(JSON.stringify(old)));assert(!Object.hasOwn(writes,D.previewSizeKey));check('New backups include preview size and old schema-1 backups preserve the current size when the optional key is absent');
 for(const value of [{scale:0},{scale:4},{scale:'1.1'},{scale:1.1,extra:true}])assert.throws(()=>B.validate({[D.previewSizeKey]:value}));const invalid=await request({action:'set',revision:state.revision,writes:{[D.previewSizeKey]:{scale:1.1,extra:true}}});assert.equal(invalid.ok,false);assert(fs.readFileSync(file).equals(before));check('Browser backup and native store validate the same strict optional size shape before writing');
}catch(error){errors.push(error.stack);console.error(error);process.exitCode=1;}finally{fs.writeFileSync(path.join(__dirname,'preview-size-verification.json'),JSON.stringify({version:'0.18.6',run,checks:report,errors,binarySHA256:require('crypto').createHash('sha256').update(fs.readFileSync(path.join(home,'PointResizeVideo.exe'))).digest('hex')},null,2));console.log('RESULT',report.length,'errors',errors.length);}})();
'''
Path(__file__).with_name('verify-preview-size.cjs').write_text(prefix+body,encoding='utf-8');print('Created focused native size and backup checks')
